"""Deterministic synthetic reference, generated by explicit window arithmetic."""
from pathlib import Path
import sys
import csv
import json
import hashlib
import numpy as np
ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from backend.vital import q15_of_mean, fir_process, load_fir_coeffs

times = np.arange(120) / 30
light = 1 + .2 * np.sin(2 * np.pi * 2 * times)
pulse = np.sin(2 * np.pi * 1.2 * times)
rgb = [120., 90., 70.] * light[:, None] * (1 + pulse[:, None] * [.002, .01, .001])
wave, support = np.zeros(len(times)), np.zeros(len(times))
for start in range(len(times) - 48 + 1):
    block = rgb[start:start + 48]
    normalized = block / block.mean(axis=0)
    r, g, b = normalized.T
    first, second = g - b, g + b - 2 * r
    projected = first + first.std() / second.std() * second
    wave[start:start + 48] += projected - projected.mean()
    support[start:start + 48] += 1
wave /= support
means = 128 * (1 + wave)
quantized = [q15_of_mean(value) for value in means]
coeffs, shift, fs = load_fir_coeffs()
filtered, saturation, _ = fir_process(quantized, coeffs, shift)
assert fs == 30 and saturation == 0
path = ROOT / 'data/golden/rppg_pos_synthetic.csv'
with path.open('w', newline='', encoding='utf-8') as stream:
    writer = csv.writer(stream)
    writer.writerow(['frame_id', 'time_s', 'mean_r', 'mean_g', 'mean_b', 'pos', 'equivalent_mean', 'q15', 'fir'])
    for fid in range(len(times)):
        writer.writerow([fid, repr(times[fid]), *map(repr, map(float, rgb[fid])),
                         repr(wave[fid]), repr(means[fid]), quantized[fid], filtered[fid]])
print(json.dumps({'file': str(path.relative_to(ROOT)), 'samples': len(times),
                  'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'saturation': saturation}))
